import fitz

# Check links and annotations in all papers
for pnum in [1, 2, 3]:
    doc = fitz.open(f"/root/paper{pnum}.pdf")
    print(f"\n=== PAPER {pnum}: Links/annotations on first 2 pages ===")
    for i in range(min(3, doc.page_count)):
        page = doc[i]
        links = page.get_links()
        for link in links:
            if 'uri' in link:
                uri = link['uri']
                if any(kw in uri.lower() for kw in ['github.com/linyueqian', 'duke.edu', 'adobe.com', 'cmu.edu', 'arxiv.org/abs/2509']):
                    print(f"  Page {i+1} link: {uri}")
        annots = page.annots()
        if annots:
            for annot in annots:
                print(f"  Page {i+1} annot: {annot.info}")
    doc.close()

# Also check the arXiv stamp location on paper 1 page 1
doc = fitz.open("/root/paper1.pdf")
page = doc[0]
# Get text with positions
blocks = page.get_text("dict")["blocks"]
for block in blocks:
    if "lines" in block:
        for line in block["lines"]:
            text = "".join([span["text"] for span in line["spans"]])
            if "arxiv" in text.lower() or "2509" in text:
                print(f"\narXiv stamp text: '{text}'")
                print(f"  bbox: {line['bbox']}")
                for span in line["spans"]:
                    print(f"  span: '{span['text']}' at {span['bbox']}, font={span['font']}, size={span['size']}")
doc.close()
